const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.heart}"/></svg>`;
const av=(role,size='')=>`<span class="avatar ${role} ${size}">${PEOPLE[role]?.initials||'J'}</span>`;
const ib=(action,name,label,extra='')=>`<button class="icon-btn" data-action="${action}" aria-label="${esc(label)}" ${extra}>${icon(name)}</button>`;
const state={config:null,key:null,demo:false,events:[],page:'home',status:'Connecting',paired:false,roleChoice:'hyu',profileRole:null,profileTab:'posts',createKind:'post',createMedia:null,chatMedia:null,verificationErrors:0,syncing:false,cursor:0,modal:null,storyIndex:0,stories:[],bookmarks:new Set(JSON.parse(localStorage.getItem('jazzy-bookmarks')||'[]'))};
let model=derive([]),toastTimer,dbPromise;
const me=()=>state.config?.role||'hyu';
const partner=()=>me()==='hyu'?'jasmin':'hyu';
const person=r=>model.profiles[r]||PEOPLE[r];
const dateLabel=value=>new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric'});
function ago(value){const n=Math.max(0,Date.now()-Date.parse(value));return n<60000?'Just now':n<3600000?Math.floor(n/60000)+'m ago':n<86400000?Math.floor(n/3600000)+'h ago':dateLabel(value);}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
function refreshModel(){model=derive(state.events);if(state.config?.name)model.profiles[me()]={...model.profiles[me()],name:state.config.name,handle:state.config.username};}
function safeMedia(src){return /^data:(image\/(jpeg|png|webp)|video\/(mp4|webm)|audio\/(webm|mp4|ogg));base64,[A-Za-z0-9+/=]+$/.test(src||'')||['demo-gwangju.svg','demo-azul.svg'].includes(src);}
function media(src,classes='',controls=true){if(!safeMedia(src))return '';if(src.startsWith('data:video/'))return `<video class="${classes} post-video" src="${esc(src)}" ${controls?'controls':''} playsinline preload="metadata"></video>`;if(src.startsWith('data:audio/'))return `<audio src="${esc(src)}" controls preload="metadata"></audio>`;return `<img class="${classes}" src="${esc(src)}" alt="Shared moment" loading="lazy">`;}
async function vaultRead(){if(!window.Jazzy)return null;const raw=Jazzy.readVault();if(raw==='!LOCKED')throw new Error('This phone could not unlock its saved keys. Do not clear app data if you need to recover this pair.');return raw?JSON.parse(raw):null;}
async function vaultWrite(config){if(window.Jazzy){const result=Jazzy.writeVault(config?JSON.stringify(config):'');if(result!=='ok')throw new Error('Could not securely save this phone’s keys.');}}
async function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('jazzy-encrypted-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('events',{keyPath:'key'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return dbPromise;}
async function cache(envelope,pending=false){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('events','readwrite');tx.objectStore('events').put({key:envelope.room+':'+envelope.id,envelope,pending});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function cached(room){const database=await db();return new Promise((resolve,reject)=>{const r=database.transaction('events').objectStore('events').getAll();r.onsuccess=()=>resolve(r.result.filter(x=>x.envelope.room===room));r.onerror=()=>reject(r.error);});}
async function removeCached(id,room=state.config.room){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('events','readwrite');tx.objectStore('events').delete(room+':'+id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function api(path,{method='GET',body,token,config=state.config}={}) {
  const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),65000);
  try{
    const response=await fetch(config.server+path,{method,headers:{...((config.session||state.auth?.session)?{'X-Jazzy-Session':config.session||state.auth.session}:{}),...(token||config.token?{Authorization:'Bearer '+(token||config.token)}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:controller.signal,redirect:'error',credentials:'omit',cache:'no-store'});
    const raw=await response.text();let data;try{data=JSON.parse(raw);}catch{throw new Error('The cloud returned a temporary hosting page. Wait a minute and try again.');}if(response.status===404&&path==='/v2/bootstrap')throw new Error('Your server needs the JAZZY 1.1 update. Deploy the included server folder on Render, then try again.');if(!response.ok){const error=new Error(data.error||'The server could not complete this request.');error.status=response.status;throw error;}return data;
  }catch(error){if(error.name==='AbortError')throw new Error('JAZZY cloud timed out. Free hosting may take a minute to wake; please retry.');if(error instanceof TypeError)throw new Error('Cannot reach JAZZY cloud. Check internet, app networking, and https://jazzy-2.onrender.com/health.');throw error;}finally{clearTimeout(timeout);}
}
function roomPath(suffix){return '/v1/rooms/'+state.config.room+'/'+suffix;}
async function receive(envelope,pending=false){const payload=await open(state.key,state.config.room,envelope);if(!validatePayload(payload))throw new Error('Invalid encrypted content');const item={...envelope,data:payload,pending};const index=state.events.findIndex(x=>x.id===item.id);if(index<0)state.events.push(item);else state.events[index]=item;state.cursor=Math.max(state.cursor,envelope.seq||0);return item;}
async function publish(payload){
  if(state.demo){const item={id:randomToken(16),author:me(),created:new Date().toISOString(),seq:state.events.length+1,data:payload};state.events.push(item);refreshModel();return item;}
  if(!state.config||!state.key)throw new Error('Connect your two phones first.');
  if(!validatePayload(payload))throw new Error('This content cannot be shared.');
  const config=state.config;const envelope=await seal(state.key,config.room,config.role,payload);await cache(envelope,true);await receive(envelope,true);refreshModel();
  try{const result=await api(roomPath('events'),{method:'POST',body:envelope});if(state.config!==config)return;const complete={...envelope,seq:result.seq};await cache(complete,false);await receive(complete,false);refreshModel();state.status='Connected';}
  catch(error){if(error.status&&error.status<500&&error.status!==429){await removeCached(envelope.id,config.room);state.events=state.events.filter(e=>e.id!==envelope.id);refreshModel();throw error;}state.status='Offline';toast('Saved on this phone. Will send when connected.');}
  return state.events.find(e=>e.id===envelope.id);
}
async function sync(){
  if(!state.demo&&state.config?.identity)await pollFriends();
  if(state.demo||!state.key||state.syncing||document.hidden)return;
  const config=state.config;state.syncing=true;let changed=false;
  try{
    const status=await api(roomPath('status'));if(state.config!==config)return;
    changed=state.paired!==status.paired;state.paired=status.paired;
    if(state.paired&&config.join){delete config.join;await vaultWrite(config);}
    const queued=(await cached(config.room)).filter(x=>x.pending);
    for(const row of queued.slice(0,5)){
      try{const result=await api(roomPath('events'),{method:'POST',body:row.envelope});if(state.config!==config)return;const complete={...row.envelope,seq:result.seq};await cache(complete);await receive(complete);changed=true;}
      catch(error){if(error.status&&error.status<500&&error.status!==429){state.status='Sync issue';toast(error.message);return;}throw error;}
    }
    // Use a separate acknowledged download cursor: outgoing events cannot skip incoming events.
    let more=true;
    while(more){const page=await api(roomPath('events')+'?after='+(state.downloadCursor||0));if(state.config!==config)return;
      for(const envelope of page.events){if(!state.events.some(e=>e.id===envelope.id&&!e.pending)){
        try{await receive(envelope);await cache(envelope);changed=true;}catch{state.verificationErrors++;changed=true;}
      }}state.downloadCursor=page.cursor;more=page.more;
    }
    state.status='Connected';refreshModel();if(changed)repaint();else updateStatus();if(state.page==='chat')await markRead();
  }catch(error){if(state.config===config){state.status=error.status===401?'Log in again':'Offline';if(error.status===401){state.config=null;state.key=null;state.events=[];state.auth=null;login(config.server,config.username||'');toast('Please log in again.');}else updateStatus();}}
  finally{state.syncing=false;}
}
async function activate(config){state.auth={server:config.server,session:config.session,role:config.role,username:config.username,name:config.name};state.config=config;state.demo=false;state.key=await eventKey(config.key,config.room);state.events=[];state.cursor=0;state.downloadCursor=0;state.verificationErrors=0;state.paired=false;state.status='Connecting';state.page='home';for(const row of await cached(config.room)){try{await receive(row.envelope,row.pending);}catch{state.verificationErrors++;}}refreshModel();render();sync();consumeShare();}
function demo(){state.config={role:'hyu'};state.demo=true;state.paired=true;state.status='Preview';state.events=[];const now=Date.now();const add=(author,data,ms)=>{const e={id:randomToken(16),seq:state.events.length+1,author,created:new Date(now-ms).toISOString(),data};state.events.push(e);return e.id;};
  const post=add('hyu',{kind:'post',media:'demo-gwangju.svg',caption:'Same sky, different cities. This one’s for you ☁️',location:'Gwangju, South Korea',sample:true},7200000);
  add('jasmin',{kind:'like',target:post,active:true},7100000);
  add('jasmin',{kind:'comment',target:post,text:'Saving a little blue for you, too. 🦋'},7000000);
  add('jasmin',{kind:'post',media:'demo-azul.svg',caption:'A small corner of my world, sent to yours. 💙',location:'Azul',sample:true},3600000);
  add('jasmin',{kind:'story',media:'demo-azul.svg',caption:'Wish you were here ☀️',sample:true},2700000);
  add('hyu',{kind:'message',text:'A little space just for us. 💙'},1800000);
  add('jasmin',{kind:'message',text:'Gwangju to Azul, a little closer. ☁️'},1700000);
  state.page='home';state.profileRole=null;state.createMedia=null;state.chatMedia=null;refreshModel();render();}
function shell(content,title='',actions=''){
  const hasUnread=model.messages.some(e=>e.author===partner())&&model.messages.filter(e=>e.author===partner()).at(-1)?.id!==model.read[me()];
  let header=title?`<h2>${esc(title)}</h2>`:`<div class="title-group"><span class="wordmark">JAZZY<span>✦</span></span></div>`;
  if(state.page==='chat')header=`<div class="chat-person">${av(partner())}<div><strong>${esc(person(partner()).name)}</strong><small>${esc(person(partner()).city)} · just you two</small></div></div>`;
  const defaultActions=ib('activity','heart','Activity')+`<button class="icon-btn" data-action="nav" data-page="chat" aria-label="Messages">${icon('send')}${hasUnread?'<span class="dot"></span>':''}</button>`;
  return `<header class="topbar">${header}<div class="header-actions">${actions||defaultActions}</div></header>${state.demo?'<div class="preview-banner"><span>Preview · sample moments, only on this phone</span><button data-action="connect">Connect us '+icon('arrow')+'</button></div>':''}${state.verificationErrors?'<div class="error-note">Some received content could not be verified and was hidden. Check your safety codes.</div>':''}${content}<nav class="nav" aria-label="Main navigation">${[['home','home','Home'],['reels','reels','Reels'],['create','plus','Create'],['chat','chat','Chat'],['profile','grid','Us']].map(([page,ico,label])=>`<button class="${state.page===page?'active':''} ${page==='create'?'create-nav':''}" data-action="nav" data-page="${page}" aria-label="${label}" ${state.page===page?'aria-current="page"':''}>${page==='create'?'<span>'+icon(ico)+'</span>':page==='profile'?av(me(),'tiny-avatar'):icon(ico)}${page!=='create'?label:''}</button>`).join('')}</nav>`;
}
function welcome(){return `<main class="welcome"><div class="welcome-head"><span class="wordmark">JAZZY<span>✦</span></span><span class="pill">${icon('lock')} Just us</span></div><div class="welcome-art" aria-hidden="true"><div class="orbit"></div><span class="sparkle">✦</span><span class="sparkle two">✧</span><div class="floating-card"><img src="demo-gwangju.svg" alt=""><div class="card-bottom"><span>Gwangju</span>${icon('moon')}</div></div><div class="floating-card second"><img src="demo-azul.svg" alt=""><div class="card-bottom"><span>Azul</span>${icon('sun')}</div></div><div class="art-heart">${icon('heart')}</div></div><div class="welcome-copy"><div class="eyebrow">HYU SUK & JAZZY</div><h1>Two worlds.<br>One <em>little space.</em></h1><p>The everyday moments. The reels that made you smile. The words only you two share.</p></div><div class="welcome-actions"><button class="btn full" data-action="login">Log in to JAZZY ${icon('arrow')}</button><button class="btn ghost full" data-action="login">Connect my account</button><button class="text-btn" data-action="demo">Take a look around first</button></div><div class="welcome-footer">${icon('lock')} Made for two. Kept between two.</div></main>`;}
function setup(join=false){if(!state.auth){login();return;}state.roleChoice=state.auth.role;state.page=join?'join':'setup';const draft=state.config?.state==='creating'?state.config:null;$('#app').innerHTML=`<main class="setup-page"><div class="back-row">${ib('welcome','back','Back')}</div><div class="eyebrow">${join?'YOUR INVITATION':'A SPACE FOR TWO'}</div><h1>${join?'You belong here.':'Let’s connect you.'}</h1><p>${join?'Paste the private invite your partner sent you. It connects this phone to your shared space.':'Your cloud server is connected automatically. The first person creates the space using a one-time private activation key.'}</p><form id="${join?'join-form':'setup-form'}" class="form-stack">${join?'<label class="field">Your private invite<textarea id="invite" autocomplete="off" spellcheck="false" placeholder="jazzy1.…" required></textarea><small>Invites expire after 72 hours and can connect one phone.</small></label>':`<label class="field">Logged in account</label><div class="role-picker">${[state.auth.role].map(r=>`<button type="button" class="role-choice ${state.roleChoice===r?'selected':''}" disabled data-role="${r}">${av(r)}<span>${PEOPLE[r].name}<small>${PEOPLE[r].city}</small></span></button>`).join('')}</div><label class="field">Cloud server<input id="server" type="url" value="${CLOUD_SERVER}" readonly required></label><label class="field">Server setup key<input id="setup-token" type="password" autocomplete="off" spellcheck="false" placeholder="One-time activation key from the server owner" required><small>Only required for first-time activation; never stored on this phone.</small></label>`}<div id="form-error" hidden class="inline-error" role="alert"></div><button class="btn full" type="submit">${join?'Join our space':'Create & get an invite'} ${icon('arrow')}</button><p class="form-help">${window.Jazzy?'Your pair key will be protected on this phone using Android Keystore.':'Browser preview: pairing keys stay only in memory. Use the Android APK for durable, protected storage.'}<br>${join?'Send invitations privately. Anyone with an unused invite can take the second place.':'Your JAZZY cloud connection is configured automatically.'}</p></form></main>`;}
function empty(ico,title,text,button='',action='create'){return `<div class="empty"><div class="empty-icon">${icon(ico)}</div><h3>${title}</h3><p>${text}</p>${button?`<button class="btn" data-action="${action}">${button} ${icon('plus')}</button>`:''}</div>`;}
function home(){const other=partner();return shell(`<main class="page">${!state.demo&&!state.paired?`<div class="connection-banner">${icon('users')}<div class="grow"><strong>Room for your favorite person.</strong><br>Add ${esc(person(other).name)} by username to connect.</div><button data-action="friends">Friends</button></div>`:''}<div class="stories"><button class="story" data-action="new-story"><span class="story-ring empty">${av(me(),'large')}<span class="add-badge">+</span></span><span>Your story</span></button><button class="story" data-action="story" data-role="${other}"><span class="story-ring ${model.stories.some(e=>e.author===other)?'':'empty'}">${av(other,'large')}</span><span>${person(other).name}</span></button>${model.stories.some(e=>e.author===me())?`<button class="story" data-action="story" data-role="${me()}"><span class="story-ring">${av(me(),'large')}</span><span>Your moments</span></button>`:''}<button class="story" data-action="safety"><span class="story-ring empty"><span class="avatar large special">${icon('lock')}</span></span><span>Only us</span></button></div><div class="feed-intro"><h2>Our little world</h2><span class="pill">${icon('users')} Just 2</span></div>${model.posts.length?model.posts.map(postCard).join(''):empty('image','The first of many.','A view from your window. Your morning coffee. Share a little piece of your day.','Share our first moment')}<div class="couple-strip"><div><strong>${esc(person('hyu').city)}</strong>${clock('hyu')}</div>${icon('heart')}<div class="right"><strong>${esc(person('jasmin').city)}</strong>${clock('jasmin')}</div></div><button class="status-line" data-action="sync" id="sync-status">${icon('lock')} ${esc(state.status)}${state.demo?'':' · Tap to refresh'}</button></main>`);}
function clock(role){try{return new Intl.DateTimeFormat('en',{hour:'2-digit',minute:'2-digit',hour12:true,timeZone:person(role).timezone}).format(new Date());}catch{return 'Set your time zone';}}
function postCard(post){const p=post.data,likes=model.likes.get(post.id)||new Set(),comments=model.comments.filter(e=>e.data.target===post.id);return `<article class="post" data-post="${post.id}"><div class="post-head">${av(post.author)}<div class="identity"><strong>${esc(person(post.author).handle)}</strong><small>${esc(p.location||person(post.author).city)}${post.pending?' · Waiting to send':''}</small></div>${ib('post-menu','more','Post options',`data-id="${post.id}"`)}</div><div class="post-art">${media(p.media,'post-media')}${p.sample?'<span class="sample">Sample illustration</span>':''}</div><div class="post-actions"><button data-action="like" data-id="${post.id}" class="${likes.has(me())?'liked':''}" aria-label="${likes.has(me())?'Unlike':'Like'} post">${icon('heart')}</button><button data-action="comments" data-id="${post.id}" aria-label="Comments">${icon('chat')}</button><button data-action="share-post" data-id="${post.id}" aria-label="Send to partner">${icon('send')}</button><span class="spacer"></span><button data-action="bookmark" data-id="${post.id}" class="${state.bookmarks.has(post.id)?'saved':''}" aria-label="${state.bookmarks.has(post.id)?'Unsave':'Save'} post">${icon('bookmark')}</button></div><div class="post-content">${likes.size?`<div class="likes">${likes.size===2?'Liked by both of you':`Liked by ${esc(person([...likes][0]).name)}`}</div>`:''}<p class="caption"><strong>${esc(person(post.author).handle)}</strong>${esc(p.caption||'A little moment, just for us.')}<br></p><button class="text-btn" data-action="comments" data-id="${post.id}">${comments.length?'View '+comments.length+' comment'+(comments.length>1?'s':''):'Leave a little love…'}</button><span class="timestamp">${ago(post.created)}</span></div></article>`;}
function reels(){return shell(`<main class="page"><div class="page-heading"><div><div class="eyebrow">SAVED WITH A SMILE</div><h1>For you, from me.</h1></div><button class="icon-btn primary" data-action="new-reel" aria-label="Share a Reel">${icon('plus')}</button></div><p class="reel-info">Share an Instagram Reel to JAZZY from Instagram’s share menu, or paste its link here. Tap a saved Reel to watch in Instagram.</p>${model.reels.length?model.reels.map((r,i)=>`<article class="reel-card ${i%2?'alt':''}">${r.data.media?media(r.data.media):`<div class="reel-poster"><span class="play">${icon('reels')}</span><small>One for our collection</small></div>`}<div class="reel-bottom"><div class="reel-owner">${av(r.author)}<span>${esc(person(r.author).handle)}</span></div><p class="reel-caption">${esc(r.data.caption||'This made me think of you. 💙')}</p><div class="reel-open">${r.data.url?`<button class="btn" data-action="open-reel" data-id="${r.id}">${icon('play')} Watch on Instagram ${icon('arrow')}</button>`:'<span class="pill">Our own little Reel</span>'}<button class="icon-btn ${(model.likes.get(r.id)||new Set()).has(me())?'liked':''}" data-action="like" data-id="${r.id}" aria-label="Like Reel">${icon('heart')}</button>${ib('post-menu','more','Reel options',`data-id="${r.id}"`)}</div></div></article>`).join(''):empty('reels','Our shared rabbit hole.','The funny ones. The travel dreams. The “this is so us” ones. Save them here.','Share a Reel','new-reel')}</main>`,'Reels',ib('instagram','reels','Open Instagram Reels'));}
function create(){return shell(`<main class="page"><div class="page-heading"><div><div class="eyebrow">A LITTLE PIECE OF YOUR DAY</div><h1>Make a memory.</h1></div></div><div class="section-pad"><div class="segmented">${[['post','Post'],['story','Story · 24h'],['reel','Reel']].map(([kind,label])=>`<button class="${state.createKind===kind?'active':''}" data-action="create-kind" data-kind="${kind}">${label}</button>`).join('')}</div><form id="create-form" class="create-form">${state.createKind==='reel'?`<label class="field">Instagram Reel link<input id="reel-url" type="url" placeholder="https://www.instagram.com/reel/…" value="${esc(state.pendingReel||'')}" autocomplete="off"><small>Paste a link, or upload your own short video below.</small></label>`:''}<button type="button" class="dropzone" data-action="pick-media" aria-label="Choose photo or video">${state.createMedia?media(state.createMedia)+'<span class="replace">Choose another</span>':icon(state.createKind==='reel'?'reels':'image')+`<strong>${state.createKind==='reel'?'Add your own video':'Choose a photo or video'}</strong><small>${state.createKind==='reel'?'MP4 or WebM · up to 8 MB':'Photos are resized · videos up to 8 MB'}</small>`}</button><input class="hidden-input" id="create-file" type="file" accept="${state.createKind==='reel'?'video/mp4,video/webm':'image/jpeg,image/png,image/webp,video/mp4,video/webm'}"><label class="field">A few words<textarea id="caption" maxlength="2200" placeholder="Something only you two would understand…">${esc(state.captionDraft||'')}</textarea></label>${state.createKind==='post'?`<label class="field">Location (optional)<input id="location" maxlength="100" placeholder="${esc(person(me()).city)}"></label>`:''}<div id="form-error" class="inline-error" hidden role="alert"></div><button class="btn full" type="submit">Share with ${esc(person(partner()).name)} ${icon('send')}</button><p class="security-note">${icon('lock')} ${state.demo?'Preview mode: this stays on this phone.':`Only you and ${esc(person(partner()).name)} can decrypt this moment.`}${state.createKind==='story'?'<br>Stories disappear from view after 24 hours.':''}</p></form></div></main>`,'Create',ib('nav','close','Back to feed','data-page="home"'));}
function messageList(){let prior='';return model.messages.map(m=>{const day=dateLabel(m.created),label=day!==prior?`<div class="day-label">${day}</div>`:'';prior=day;const own=m.author===me(),linked=model.posts.find(p=>p.id===m.data.postId);let reel='';try{if(m.data.text?.includes('instagram.com/reel'))reel=normalizeReel(m.data.text);}catch{}return `${label}<div class="message ${own?'mine':''}" data-message="${m.id}"><div class="bubble">${m.data.media?media(m.data.media):''}${m.data.file?`<button class="file-card" data-action="download-file" data-id="${m.id}">${icon('copy')}<span>${esc(m.data.file.name)}<small>Tap to save file</small></span></button>`:''}${linked?`<button data-action="view-post" data-id="${linked.id}" aria-label="Open shared post">${media(linked.data.media)}<small>View our moment ${icon('arrow')}</small></button>`:''}${esc(m.data.text||'')}${reel?`<br><button class="text-btn blue" data-action="open-url" data-url="${esc(reel)}">Watch on Instagram ${icon('arrow')}</button>`:''}</div><small>${new Date(m.created).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}${own?' · '+(m.pending?'Waiting to send':model.read[partner()]===m.id?'Seen':'Sent'):''}</small></div>`;}).join('');}
function chat(){return shell(`<main class="page chat-page"><div class="encryption-note">${icon('lock')} ${state.demo?'Preview conversation · sample messages':'Messages and media are end-to-end encrypted.'}<br>${state.demo?'Try sending a message. It stays in this preview.':'Compare your safety codes in settings.'}</div><div class="messages" id="messages">${model.messages.length?messageList():empty('chat','Your own quiet corner.','Say the thing you’ve been waiting to say. 💙')}</div></main><form id="chat-form" class="chat-compose"><div id="chat-attachment">${chatAttachment()}</div><div class="chat-input-row"><button type="button" class="icon-btn" data-action="chat-pick" aria-label="Attach a photo, video, audio clip, or file">${icon('plus')}</button><textarea id="message" aria-label="Message" placeholder="A message, just for ${esc(person(partner()).name)}…" maxlength="5000" rows="1"></textarea><button class="icon-btn send-btn" type="submit" aria-label="Send message">${icon('send')}</button></div><input class="hidden-input" id="chat-file" type="file" accept="*/*"></form>`,'',ib('safety','lock','Encryption and safety code'));}
function chatAttachment(){if(state.chatFile)return `<div class="attachment-preview">${icon('copy')}<span>${esc(state.chatFile.name)}</span><button type="button" data-action="remove-attachment" aria-label="Remove attachment">${icon('close')}</button></div>`;return state.chatMedia?`<div class="attachment-preview">${state.chatMedia.startsWith('data:image')?media(state.chatMedia):icon('image')}<span>Attachment ready</span><button type="button" data-action="remove-attachment" aria-label="Remove attachment">${icon('close')}</button></div>`:'';}
function profile(){const role=state.profileRole||me(),p=person(role),own=role===me(),posts=state.profileTab==='saved'?model.posts.filter(e=>state.bookmarks.has(e.id)):model.posts.filter(e=>e.author===role);return shell(`<main class="page"><section class="profile-hero"><div class="profile-top"><div class="profile-ring">${av(role,'big')}</div><div class="profile-stats"><div><strong>${model.posts.filter(e=>e.author===role).length}</strong><small>moments</small></div><div><strong>1</strong><small>favorite person</small></div></div></div><div class="profile-info"><h2>${esc(p.name)}</h2><p class="location">${esc(p.city)} · ${clock(role)}</p><p class="bio">${esc(p.bio)}</p></div><div class="profile-buttons">${own?'<button class="btn secondary" data-action="edit-profile">Edit profile</button>':`<button class="btn secondary" data-action="nav" data-page="chat">Message ${esc(p.name)}</button>`}<button class="btn ghost" data-action="show-partner">${own?`See ${esc(person(partner()).name)}’s profile`:'Back to my profile'}</button></div></section><div class="pair-card">${av(own?partner():me())}<div class="grow"><h3>Two cities. One connection.</h3><p>${esc(person('hyu').city)} & ${esc(person('jasmin').city)}<br>A private little world for Hyu Suk & Jazzy.</p></div>${icon('heart')}</div><div class="profile-tabs"><button data-action="profile-tab" data-tab="posts" class="${state.profileTab==='posts'?'active':''}">${icon('grid')} Moments</button>${own?`<button data-action="profile-tab" data-tab="saved" class="${state.profileTab==='saved'?'active':''}">${icon('bookmark')} Saved</button>`:''}</div>${posts.length?`<div class="photo-grid">${posts.map(e=>`<button data-action="view-post" data-id="${e.id}" aria-label="Open moment">${media(e.data.media,'',false)}${e.data.media?.startsWith('data:video')?icon('reels'):''}</button>`).join('')}</div>`:empty(state.profileTab==='saved'?'bookmark':'grid',state.profileTab==='saved'?'Keep your favorites close.':'A story, still being written.',state.profileTab==='saved'?'Tap the bookmark on a post to save it on this phone.':'Your shared moments will appear here.')}</main>`,p.handle,ib('settings','settings','Settings'));}
function activity(){const list=state.events.filter(e=>e.author!==me()&&(['comment','post','story','reel'].includes(e.data.kind)||e.data.kind==='like'&&e.data.active)).reverse().slice(0,40);return shell(`<main class="page"><div class="page-heading"><h1>A little love.</h1></div>${list.length?list.map(e=>`<div class="activity-item">${av(e.author)}<p><strong>${esc(person(e.author).name)}</strong> ${e.data.kind==='like'?'liked a moment.':e.data.kind==='comment'?'left you a comment.':'shared a '+e.data.kind+'.'}<small>${ago(e.created)}</small></p>${icon(e.data.kind==='like'?'heart':e.data.kind==='comment'?'chat':'image')}</div>`).join(''):empty('heart','Just the little things.','Likes, comments, and new moments from your partner will appear here.')}</main>`,'Activity',ib('nav','back','Back to feed','data-page="home"'));}
function render(){refreshModel();if(state.config&&!state.demo&&state.config.state!=='active'){lobby();return;}if(!state.config){$('#app').innerHTML=welcome();return;}const pages={home,reels,create,chat,profile,activity};$('#app').innerHTML=(pages[state.page]||home)();if(state.page==='chat')requestAnimationFrame(()=>window.scrollTo(0,document.body.scrollHeight));}
function repaint(){if(state.modal||state.page==='create'||['setup','join'].includes(state.page))return;if(state.page==='chat'){const container=$('#messages');if(container){const nearBottom=window.innerHeight+window.scrollY>=document.body.scrollHeight-140;container.innerHTML=messageList();if(nearBottom)window.scrollTo(0,document.body.scrollHeight);}return;}const y=window.scrollY;render();window.scrollTo(0,y);}
function updateStatus(){const el=$('#sync-status');if(el){el.classList.toggle('offline',state.status!=='Connected');el.innerHTML=icon(state.status==='Connected'?'lock':'refresh')+' '+esc(state.status)+' · Tap to refresh';}}
function navigate(page){closeModal();state.page=page;state.profileRole=null;render();window.scrollTo(0,0);if(page==='chat')markRead();}
let lastReadSending=null;
async function markRead(){const last=model.messages.filter(e=>e.author===partner()).at(-1);if(!last||model.read[me()]===last.id||lastReadSending===last.id)return;lastReadSending=last.id;try{await publish({kind:'read',target:last.id});}catch{}finally{lastReadSending=null;}}
function sheet(title,content,id='sheet'){state.modal=id;$('#overlay').innerHTML=`<div class="modal-scrim" data-action="scrim"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-handle"></div><div class="sheet-head"><h2>${title}</h2>${ib('close','close','Close dialog')}</div>${content}</section></div>`;setTimeout(()=>$('#overlay button, #overlay input')?.focus(),30);}
function closeModal(){state.modal=null;$('#overlay').innerHTML='';}
function settings(){sheet('Our space',`<button class="settings-row" data-action="safety">${icon('lock')}<span class="grow">Encryption & safety code<small>Compare the code on your two phones.</small></span>${icon('chevron')}</button>${!state.paired&&!state.demo?`<button class="settings-row" data-action="invite">${icon('users')}<span class="grow">Friends<small>Add your partner by username.</small></span>${icon('chevron')}</button>`:''}<button class="settings-row" data-action="edit-profile">${icon('pin')}<span class="grow">Profile & local time<small>Set your city, bio, and time zone.</small></span>${icon('chevron')}</button>${!state.demo?'<button class="settings-row" data-action="account">'+icon('users')+'<span class="grow">Account & password<small>Change your name, username, or password.</small></span>'+icon('chevron')+'</button><button class="settings-row" data-action="logout">'+icon('lock')+'<span class="grow">Log out<small>Keep this phone’s encrypted keys for your next login.</small></span></button>':''}<button class="settings-row" data-action="about">${icon('info')}<span class="grow">About JAZZY<small>Version 1.1.1 · made for two.</small></span>${icon('chevron')}</button>${state.demo?'<button class="settings-row" data-action="switch-demo">'+icon('users')+'<span class="grow">Preview as '+esc(person(partner()).name)+'</span>'+icon('chevron')+'</button><button class="settings-row" data-action="connect">'+icon('link')+'<span class="grow">Connect our phones</span>'+icon('chevron')+'</button>':`<div class="security-note">${esc(state.status)}<br><span class="mono">${esc(state.config.server)}</span></div>`}<button class="settings-row danger" data-action="forget-prompt">${icon('trash')}<span class="grow">${state.demo?'Leave preview':'Forget this phone'}<small>${state.demo?'Discard the sample session.':'Erases local keys. Pairing cannot be restored without a backup.'}</small></span></button>`);}
async function safety(){const code=state.demo?'DEMO ONLY · NO SHARED KEYS':await safetyCode(state.config.key,state.config.room);sheet('Kept between two.',`<p>${state.demo?'Pair your phones to create a shared encryption key.':'Read this code to each other over a trusted call. Both phones should show exactly the same code.'}</p><div class="safety-code">${code}</div><p>JAZZY encrypts messages, posts, stories, and media on your phones with AES-256-GCM. The server stores ciphertext and cannot decrypt it without your pair key.</p><p>Compare this code after accepting a friend request: the server supplies account public keys, so this comparison helps detect key substitution. This version has no forward secrecy and has not had an independent security audit. A compromised phone can expose your conversation.</p><button class="btn secondary full" data-action="close">Got it ${icon('check')}</button>`);}
async function invite(){if(state.demo){setup();return;}if(state.paired){toast('You are already connected.');return;}if(!state.config.owner){toast('Only the pair creator can make an invite.');return;}if(!state.config.join){state.config.join=randomToken();await api(roomPath('invite'),{method:'POST',body:{join:state.config.join}});await vaultWrite(state.config);}const text=makeInvite(state.config,state.config.join);sheet('One invitation. Only them.',`<p>Send this invite privately to ${esc(person(partner()).name)}. It contains your encryption key and opens the second place in JAZZY. It expires after 72 hours.</p><textarea class="invite-text" readonly aria-label="Private pairing invite">${esc(text)}</textarea><button class="btn full" data-action="share-invite">${icon('send')} Share private invite</button><button class="text-btn" data-action="refresh-invite">Create a fresh invite</button><p class="notice">Keep both phones and their screen locks secure. Once your partner joins, this invite cannot add another phone.</p>`,'invite');}
function comments(id){const post=model.posts.find(p=>p.id===id);if(!post)return;const list=model.comments.filter(e=>e.data.target===id);sheet('A little love',`<div class="comment-list">${list.length?list.map(e=>`<div class="comment">${av(e.author)}<div><p><strong>${esc(person(e.author).handle)}</strong>${esc(e.data.text)}</p><small>${ago(e.created)}${e.pending?' · Waiting to send':''}</small></div></div>`).join(''):'<p class="muted">Be the first to leave a little note. 💙</p>'}</div><form id="comment-form" data-id="${id}" class="comment-form"><input id="comment" maxlength="1000" placeholder="Leave a little love…" aria-label="Comment" required><button class="btn" type="submit">Send</button></form>`,'comments');}
function editProfile(){const p=person(me());sheet('A little about you',`<form id="profile-form" class="form-stack"><label class="field">Bio<textarea id="profile-bio" maxlength="180">${esc(p.bio)}</textarea></label><label class="field">City<input id="profile-city" maxlength="60" value="${esc(p.city)}" required></label><label class="field">Time zone<select id="profile-zone">${[['Asia/Seoul','South Korea · Seoul'],['America/Argentina/Buenos_Aires','Argentina · Buenos Aires'],['UTC','UTC']].map(([v,t])=>`<option value="${v}" ${p.timezone===v?'selected':''}>${t}</option>`).join('')}</select><small>Azul starts with Argentina’s time zone. Change it if needed.</small></label><button class="btn full" type="submit">Save profile ${icon('check')}</button></form>`);}
function about(){sheet('Hello, JAZZY.',`<p>A private Android space for Hyu Suk and Jazzy, in a little shade of blue.</p><ul class="about-list"><li>Shared photos and videos, likes, comments, and saved posts.</li><li>Stories visible for 24 hours.</li><li>Instagram Reel links and your own short videos.</li><li>Text, photo, video, and audio attachments in encrypted chat.</li><li>Two devices, one private invitation, no public profiles.</li></ul><p>Messages sync while the app is open. This version does not include push notifications, calls, live video, Instagram account login, or Instagram’s personalized feed. Instagram links open in the Instagram app or browser.</p><p>JAZZY is independent of Instagram and Meta. Preview illustrations and conversations are samples, not your photos or real messages.</p><p class="security-note">Android 8+ · Version 1.0<br>Server deployment is required for two-phone sharing. Protect your devices: this release has not been independently security-audited.</p>`);}
function viewStory(role){const stories=model.stories.filter(e=>e.author===role);if(!stories.length){toast(role===me()?'Add your first story.':'No story yet. A new moment will appear here.');return;}state.stories=stories;state.storyIndex=0;renderStory();}
function renderStory(){const story=state.stories[state.storyIndex];if(!story){closeModal();return;}state.modal='story';$('#overlay').innerHTML=`<section class="story-view" role="dialog" aria-modal="true" aria-label="Story"><div class="story-progress">${state.stories.map((_,i)=>`<span class="${i<=state.storyIndex?'active':''}"></span>`).join('')}</div><div class="post-head">${av(story.author)}<div class="identity"><strong>${esc(person(story.author).handle)}</strong><small>${ago(story.created)}${story.data.sample?' · Sample illustration':''}</small></div>${story.author===me()?ib('post-menu','more','Story options',`data-id="${story.id}"`):''}${ib('close','close','Close story')}</div>${media(story.data.media)}<p class="story-caption">${esc(story.data.caption||'')}</p><div class="story-controls"><button data-action="story-prev">Previous</button><button data-action="story-next">${state.storyIndex===state.stories.length-1?'Done':'Next'}</button></div></section>`;}
async function fileToMedia(file){if(!file)throw new Error('Choose a file first.');if(file.type.startsWith('image/')){
  if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Choose a JPEG, PNG, or WebP image.');if(file.size>25*1024*1024)throw new Error('Choose an image smaller than 25 MB.');
  const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(!img.width||!img.height)throw new Error('Could not read this image.');const factor=Math.min(1,1600/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*factor);canvas.height=Math.round(img.height*factor);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.85);}finally{URL.revokeObjectURL(url);}}
  if(!['video/mp4','video/webm','audio/mp4','audio/webm','audio/ogg'].includes(file.type))throw new Error('Choose an MP4/WebM video or MP4/WebM/Ogg audio file.');if(file.size>8*1024*1024)throw new Error('Use a short clip smaller than 8 MB.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read this file.'));reader.readAsDataURL(file);});}
function external(url){if(!/^https:\/\/(www\.)?instagram\.com\/(reel(s)?)(\/[A-Za-z0-9_-]+)?\/?$/.test(url))throw new Error('This link is not an Instagram Reel.');if(window.Jazzy)Jazzy.openInstagram(url);else window.open(url,'_blank','noopener,noreferrer');}
async function shareText(text){if(window.Jazzy){Jazzy.shareText(text);return;}if(navigator.share){await navigator.share({title:'JAZZY',text});return;}await navigator.clipboard.writeText(text);toast('Copied. Send it privately to your partner.');}
function consumeShare(){if(!state.config)return;const text=window.Jazzy?Jazzy.consumeSharedText():'';if(text)window.jazzyReceiveShare(text);}
window.jazzyReceiveShare=text=>{try{state.pendingReel=normalizeReel(text);state.createKind='reel';state.createMedia=null;if(state.config)navigate('create');else toast('Connect your phones first to save this Reel.');}catch{toast('Share a direct Instagram Reel link to JAZZY.');}};
window.jazzyBack=()=>{if(state.modal)closeModal();else if(state.page==='setup'||state.page==='join'||state.page==='login'||state.page==='pair-options'){state.config=null;render();}else if(state.page!=='home')navigate('home');else if(window.Jazzy)Jazzy.minimize();};

function login(server='',username=''){
  closeModal();state.page='login';state.demo=false;state.config=null;state.key=null;state.events=[];state.auth=null;state.friends=null;
  $('#app').innerHTML=`<main class="setup-page login-page"><div class="back-row">${ib('welcome','back','Back')}</div><div class="login-brand"><span class="wordmark">JAZZY<span>✦</span></span><div class="eyebrow">YOUR PERSON. YOUR PLACE.</div></div><h1>A little closer again.</h1><p>Log in, then add your person by username.</p><form id="login-form" class="form-stack"><label class="field">Username<input id="login-username" value="${esc(username)}" placeholder="hyusukk or JAZZY" autocomplete="username" maxlength="30" required></label><label class="field">Password<input id="login-password" type="password" autocomplete="current-password" placeholder="Your password" maxlength="128" required></label><label class="field">Server key<input id="login-key" type="password" autocomplete="off" placeholder="Required on your first login"><small>Use the same server key on both phones. Leave blank after this phone is registered.</small></label><div id="form-error" hidden class="inline-error" role="alert"></div><button class="btn full" type="submit">Log in ${icon('arrow')}</button></form><p class="notice">Your two private accounts. No invite codes to copy.</p></main>`;
}
async function submitLogin(){
  const server=validateServer(CLOUD_SERVER,!window.Jazzy),username=$('#login-username').value.trim(),password=$('#login-password').value,setupToken=$('#login-key').value.trim();
  if(setupToken&&!/^[A-Za-z0-9_-]{43}$/.test(setupToken))throw new Error('Paste the full 43-character server key.');
  if(window.Jazzy&&Jazzy.allowServer(server)!=='ok')throw new Error('Use a valid HTTPS server address.');
  const health=await api('/health',{config:{server}});
  if(!health.features?.includes('username-friends'))throw new Error('Your cloud server is online but needs updating. Deploy the JAZZY 1.1.1 server files on Render, then log in again.');
  const result=await api('/v1/auth/login',{method:'POST',config:{server},body:{username,password}});
  const previous=await vaultRead();
  let config=previous&&previous.server===server&&previous.role===result.role?previous:{state:'lobby',server,role:result.role,token:randomToken()};
  if(!config.identity)config.identity=await createIdentity();
  Object.assign(config,{session:result.session,username:result.username,name:result.name,loggedOut:false});
  // Persist the device identity before registration so a dropped response is safely retryable.
  await vaultWrite({...config,loggedOut:true});
  await api('/v2/bootstrap',{method:'POST',config,token:setupToken||config.token,body:{token:config.token,publicKey:config.identity.publicKey}});
  $('#login-password').value='';$('#login-key').value='';state.auth={...result,server};state.config=config;await vaultWrite(config);
  if(config.state==='joining')await finishFriendJoin(config);
  else if(config.state==='active')await activate(config);
  else {state.key=null;state.events=[];state.demo=false;state.page='home';render();await pollFriends();}
  toast('Welcome home, '+result.name+'.');
}
function lobby(){
  $('#app').innerHTML=`<header class="topbar"><span class="wordmark">JAZZY<span>✦</span></span><div class="header-actions">${ib('friends','users','Friends')}${ib('account','settings','Account & password')}</div></header><main class="page"><div class="page-heading"><div class="eyebrow">@${esc(state.config.username)}</div><h1>Welcome home,<br>${esc(state.config.name)}.</h1><p>Your moments will appear here when you connect.</p></div><div class="connection-banner">${icon('users')}<div class="grow"><strong>Find your person.</strong><p>Add their username and accept the friend request to start sharing privately.</p></div></div><button class="btn full" data-action="friends">${icon('plus')} Add friend by username</button><div id="friend-summary" class="notice"></div><button class="text-btn" data-action="logout">Log out</button></main><nav class="nav" aria-label="Main navigation"><button class="active" data-action="nav" data-page="home">${icon('home')}Home</button><button data-action="friends">${icon('users')}Friends</button><button data-action="account">${icon('settings')}Account</button></nav>`;
  updateFriendsView();
}
function requestContext(sender,recipient,room){return JSON.stringify({v:2,server:state.config.server,sender,recipient,room});}
function incomingMarkup(){return (state.friends?.incoming||[]).map(r=>`<div class="connection-banner"><div class="grow"><strong>${esc(r.name)}</strong><br>@${esc(r.username)} wants to connect.</div><button class="btn" data-action="accept-friend" data-id="${esc(r.sender)}">Accept</button><button class="text-btn" data-action="decline-friend" data-id="${esc(r.sender)}">Decline</button></div>`).join('');}
function updateFriendsView(){
  const requests=$('#friend-requests');if(requests)requests.innerHTML=incomingMarkup();
  const out=state.friends?.outgoing,summary=$('#friend-summary');if(summary)summary.textContent=state.friends?.incoming?.length?'You have a friend request. Open Friends to accept it.':out?'Request sent to @'+out.username+'. Waiting for acceptance.':'Both of you can log in now. Then search the other account’s username.';
  const status=$('#friend-status');if(status)status.textContent=state.paired?'You are connected.':out?'Request sent to @'+out.username+'. Waiting for acceptance.':'';
}
async function pollFriends(){
  if(!state.config?.identity||state.demo||state.friendsPolling||document.hidden)return;
  const config=state.config;state.friendsPolling=true;
  try{const result=await api('/v2/friends');if(state.config!==config)return;state.friends=result;updateFriendsView();}catch(error){if(error.status===401)state.status='Log in again';}finally{state.friendsPolling=false;}
}
async function friends(){
  if(state.demo){login();return;}
  if(!state.config?.identity){toast('Log out and log in with your server key to enable Friends.');return;}
  closeModal();await pollFriends();
  sheet('Friends',`<p>Connect your two accounts by username.</p><div id="friend-requests">${incomingMarkup()}</div><div id="friend-status" class="notice"></div>${state.paired?'':`<form id="friend-search" class="form-stack"><label class="field">Username<input id="friend-username" placeholder="${me()==='hyu'?'JAZZY':'hyusukk'}" autocomplete="off" minlength="3" maxlength="30" required></label><div id="form-error" hidden class="inline-error" role="alert"></div><button class="btn full" type="submit">Find account</button></form><div id="friend-result"></div>`}`,'friends');updateFriendsView();
}
async function sendFriend(){
  const user=state.foundUser,config=state.config;if(!user?.publicKey)throw new Error('Your partner needs to log in first.');
  if(config.state!=='active'){
    if(config.state!=='creating')Object.assign(config,{state:'creating',owner:true,room:randomToken(16),key:randomToken(),join:randomToken()});
    await vaultWrite(config);
    await api('/v2/rooms',{method:'POST',body:{room:config.room,role:config.role,token:config.token,join:config.join}});
    config.state='active';await vaultWrite(config);
  }
  if(!config.owner)throw new Error('Open Friends and accept the request sent to you.');
  // Refresh the one-use room credential each time a request is sent.
  config.join=randomToken();await vaultWrite(config);await api(roomPath('invite'),{method:'POST',body:{join:config.join}});
  const encrypted=await sealRequest(config.identity,user.publicKey,requestContext(config.role,user.role,config.room),{invite:makeInvite(config,config.join)});
  await api('/v2/friends',{method:'POST',body:{to:user.role,room:config.room,...encrypted}});
  closeModal();await activate(config);await friends();toast('Friend request sent to @'+user.username+'.');
}
async function acceptFriend(sender){
  const request=state.friends?.incoming.find(r=>r.sender===sender);if(!request)throw new Error('Refresh Friends and try again.');
  const current=state.config;if(current.state==='active'&&current.room!==request.room)throw new Error('This phone is already connected to a different space.');
  const payload=await openRequest(current.identity,request.publicKey,requestContext(sender,current.role,request.room),request);
  const data=parseInvite(payload.invite,!window.Jazzy);
  if(data.server!==current.server||data.role!==current.role||data.room!==request.room)throw new Error('The friend request could not be verified.');
  const config={...current,state:'joining',room:data.room,key:data.key,join:data.join,owner:false};await vaultWrite(config);state.config=config;await finishFriendJoin(config);
}
async function finishFriendJoin(config){
  await api('/v1/rooms/'+config.room+'/join',{method:'POST',config,body:{invite:config.join,token:config.token}});
  config.state='active';delete config.join;await vaultWrite(config);closeModal();await activate(config);toast('Connected! Compare your safety codes in Settings.');
}
function accountSettings(){
  sheet('Your account',`<p>Change your name, username, or password. Your encrypted conversations keep the same private pair key.</p><form id="account-form" class="form-stack"><label class="field">Display name<input id="account-name" value="${esc(person(me()).name)}" maxlength="50" required></label><label class="field">Username<input id="account-username" value="${esc(state.config.username)}" minlength="3" maxlength="30" pattern="[A-Za-z0-9_.]+" required></label><label class="field">Current password<input id="current-password" type="password" autocomplete="current-password" required></label><label class="field">New password (optional)<input id="new-password" type="password" autocomplete="new-password" minlength="8" maxlength="128" placeholder="Leave blank to keep your password"></label><label class="field">Confirm new password<input id="confirm-password" type="password" autocomplete="new-password" maxlength="128"></label><div id="form-error" hidden class="inline-error" role="alert"></div><button class="btn full" type="submit">Save account ${icon('check')}</button></form>`,'account');
}
async function changeAccount(){
  const newPassword=$('#new-password').value;if(newPassword!==$('#confirm-password').value)throw new Error('The new passwords do not match.');
  const result=await api('/v1/auth/change',{method:'POST',body:{currentPassword:$('#current-password').value,username:$('#account-username').value.trim(),name:$('#account-name').value.trim(),newPassword}});
  Object.assign(state.config,{session:result.session,username:result.username,name:result.name});state.auth={...result,server:state.config.server};await vaultWrite(state.config);
  const p=person(me());if(state.config.state==='active')await publish({kind:'profile',name:result.name,handle:result.username,bio:p.bio,city:p.city,timezone:p.timezone});
  closeModal();render();toast('Your account is updated.');
}
async function logout(){
  const config=state.config;try{await api('/v1/auth/logout',{method:'POST',body:{}});}catch{}
  if(config&&!state.demo){delete config.session;config.loggedOut=true;await vaultWrite(config);}
  state.auth=null;state.config=null;state.key=null;state.events=[];state.chatMedia=null;state.chatFile=null;state.createMedia=null;login(config?.server||'',config?.username||'');
}
async function fileAttachment(file){
  if(file.size>8*1024*1024)throw new Error('Choose a file smaller than 8 MB.');
  const body=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve('data:application/octet-stream;base64,'+String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Could not read this file.'));reader.readAsDataURL(file);});
  return {name:file.name.replace(/[\/\\\x00-\x1f\u202a-\u202e]/g,'_').slice(0,180)||'shared-file',body};
}
function downloadAttachment(id){
  const file=model.messages.find(e=>e.id===id)?.data.file;if(!file)return;
  if(window.Jazzy){Jazzy.saveFile(file.name,file.body.split(',')[1]);return;}
  const a=document.createElement('a');a.href=file.body;a.download=file.name;a.click();
}
async function action(button){const a=button.dataset.action,id=button.dataset.id;
  switch(a){
    case 'welcome':closeModal();state.config=null;render();break;
    case 'demo':demo();break;
    case 'connect':closeModal();state.config=null;state.demo=false;state.events=[];state.auth=null;login();break;
    case 'login':login();break;
    case 'account':accountSettings();break;
    case 'logout':await logout();break;
    case 'download-file':downloadAttachment(id);break;
    case 'setup':await friends();break;
    case 'join':await friends();break;
    case 'role':state.roleChoice=button.dataset.role;document.querySelectorAll('.role-choice').forEach(b=>b.classList.toggle('selected',b.dataset.role===state.roleChoice));break;
    case 'nav':navigate(button.dataset.page);break;
    case 'create':state.createKind='post';state.createMedia=null;navigate('create');break;
    case 'new-story':state.createKind='story';state.createMedia=null;navigate('create');break;
    case 'new-reel':state.createKind='reel';state.createMedia=null;navigate('create');break;
    case 'create-kind':state.captionDraft=$('#caption')?.value||'';state.createKind=button.dataset.kind;state.createMedia=null;render();break;
    case 'pick-media':$('#create-file').click();break;
    case 'chat-pick':$('#chat-file').click();break;
    case 'remove-attachment':state.chatMedia=null;state.chatFile=null;$('#chat-attachment').innerHTML='';break;
    case 'activity':navigate('activity');break;
    case 'like':{const active=!(model.likes.get(id)||new Set()).has(me());button.disabled=true;await publish({kind:'like',target:id,active});repaint();break;}
    case 'bookmark':state.bookmarks.has(id)?state.bookmarks.delete(id):state.bookmarks.add(id);localStorage.setItem('jazzy-bookmarks',JSON.stringify([...state.bookmarks]));repaint();toast(state.bookmarks.has(id)?'Saved on this phone.':'Removed from saved.');break;
    case 'comments':comments(id);break;
    case 'share-post':await publish({kind:'message',text:'A little moment for you. 💙',postId:id});toast('Shared in your chat.');break;
    case 'view-post':{const p=model.posts.find(e=>e.id===id);if(p)sheet('Our moment',media(p.data.media,'image-detail')+`<p>${esc(p.data.caption)}</p><button class="btn secondary full" data-action="comments" data-id="${id}">Leave a comment</button>`);break;}
    case 'post-menu':{const e=state.events.find(e=>e.id===id);if(e)sheet('This moment',`<p>Shared by ${esc(person(e.author).name)} · ${ago(e.created)}</p>${e.author===me()?`<button class="btn danger full" data-action="delete-prompt" data-id="${id}">${icon('trash')} Remove from our space</button>`:'<button class="btn secondary full" data-action="close">Back to our space</button>'}`);break;}
    case 'delete-prompt':sheet('Remove this moment?',`<p>It will disappear from both phones after they sync. Your partner may already have seen or saved it.</p><button class="btn danger full" data-action="delete" data-id="${id}">Remove moment</button>`);break;
    case 'delete':await publish({kind:'delete',target:id});closeModal();render();toast('Moment removed from view.');break;
    case 'settings':settings();break;
    case 'safety':await safety();break;
    case 'invite':await friends();break;
    case 'friends':await friends();break;
    case 'send-friend':await sendFriend();break;
    case 'accept-friend':await acceptFriend(id);break;
    case 'decline-friend':await api('/v2/friends/decline',{method:'POST',body:{sender:id}});await friends();break;
    case 'share-invite':await shareText('Our little space on JAZZY 💙\nKeep this invite private.\n'+makeInvite(state.config,state.config.join));break;
    case 'refresh-invite':{const join=randomToken();await api(roomPath('invite'),{method:'POST',body:{join}});state.config.join=join;await vaultWrite(state.config);await invite();break;}
    case 'edit-profile':editProfile();break;
    case 'about':about();break;
    case 'show-partner':state.profileRole=(state.profileRole||me())===me()?partner():me();state.profileTab='posts';render();break;
    case 'profile-tab':state.profileTab=button.dataset.tab;render();break;
    case 'open-reel':{const reel=model.reels.find(r=>r.id===id);if(reel?.data.url)external(normalizeReel(reel.data.url));break;}
    case 'open-url':external(normalizeReel(button.dataset.url));break;
    case 'instagram':external('https://www.instagram.com/reels/');break;
    case 'sync':if(state.demo)toast('Preview mode. Connect your phones to sync.');else{toast('Checking for your partner’s moments…');await sync();}break;
    case 'story':viewStory(button.dataset.role);break;
    case 'story-next':state.storyIndex++;renderStory();break;
    case 'story-prev':state.storyIndex=Math.max(0,state.storyIndex-1);renderStory();break;
    case 'switch-demo':state.config.role=partner();closeModal();state.profileRole=null;render();break;
    case 'close':closeModal();break;
    case 'forget-prompt':sheet(state.demo?'Leave preview?':'Forget this phone?',`<p>${state.demo?'The sample session and any preview changes will be discarded.':'This erases the encryption key and cached content on this phone. You cannot rejoin an already-paired space with the old invite. The other phone and the server are not erased. Create a new pair after the server owner resets its database if you need to start over.'}</p><button class="btn danger full" data-action="forget">${state.demo?'Leave preview':'Erase this phone’s JAZZY keys'}</button>`);break;
    case 'forget':{const room=state.config?.room;if(room){for(const row of await cached(room))await removeCached(row.envelope.id,room);}await vaultWrite(null);state.config=null;state.key=null;state.demo=false;state.events=[];state.chatMedia=null;state.createMedia=null;state.bookmarks.clear();localStorage.removeItem('jazzy-bookmarks');closeModal();render();break;}
  }
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;if(button.dataset.action==='scrim'&&e.target!==button)return;if(button.dataset.action==='scrim'){closeModal();return;}Promise.resolve(action(button)).catch(error=>{toast(error.message||'Something went wrong.');button.disabled=false;});});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal)closeModal();if(e.target.id==='message'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form').requestSubmit();}if(e.key==='Tab'&&state.modal){const focusable=[...$('#overlay').querySelectorAll('button,input,textarea,select,[tabindex="0"]')].filter(x=>!x.disabled);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('input',e=>{if(e.target.id==='message'){e.target.style.height='34px';e.target.style.height=Math.min(e.target.scrollHeight,96)+'px';}if(e.target.id==='caption')state.captionDraft=e.target.value;});
document.addEventListener('change',async e=>{if(!['create-file','chat-file'].includes(e.target.id))return;try{toast('Preparing your moment…');const selected=e.target.files[0];if(e.target.id==='chat-file'&&selected&&!/^(image\/(jpeg|png|webp)|video\/(mp4|webm)|audio\/(mp4|webm|ogg))$/.test(selected.type)){state.chatFile=await fileAttachment(selected);state.chatMedia=null;$('#chat-attachment').innerHTML=chatAttachment();toast('File ready to send.');return;}const value=await fileToMedia(selected);if(e.target.id==='create-file'){if(state.createKind==='reel'&&!value.startsWith('data:video/'))throw new Error('Choose a video for your Reel.');state.createMedia=value;state.captionDraft=$('#caption')?.value||'';state.pendingReel=$('#reel-url')?.value||'';render();}else{state.chatMedia=value;state.chatFile=null;$('#chat-attachment').innerHTML=chatAttachment();}toast('Ready to share.');}catch(error){toast(error.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type="submit"]');if(button?.disabled)return;const errorEl=form.querySelector('#form-error');if(errorEl)errorEl.hidden=true;if(button)button.disabled=true;
  try{
    if(form.id==='login-form'){await submitLogin();}
    else if(form.id==='account-form'){await changeAccount();}
    else if(form.id==='friend-search'){const result=await api('/v2/users?username='+encodeURIComponent($('#friend-username').value.trim()));state.foundUser=result.user;$('#friend-result').innerHTML=`<div class="connection-banner"><div class="grow"><strong>${esc(result.user.name)}</strong><br>@${esc(result.user.username)}</div><button class="btn" data-action="send-friend" type="button" ${result.user.publicKey?'':'disabled'}>Add friend</button></div>${result.user.publicKey?'':'<p>Your partner needs to log in with the updated app first.</p>'}`;}
    else if(form.id==='setup-form'){
      const server=validateServer(CLOUD_SERVER,!window.Jazzy),setupToken=$('#setup-token').value.trim();if(!/^[A-Za-z0-9_-]{43}$/.test(setupToken))throw new Error('The setup key should contain 43 letters, numbers, dashes, or underscores.');
      const previous=await vaultRead();const config=previous?.state==='creating'&&previous.server===server?previous:{state:'creating',server,role:state.auth.role,owner:true,room:randomToken(16),token:randomToken(),join:randomToken(),key:randomToken()};
      Object.assign(config,{session:state.auth.session,username:state.auth.username,name:state.auth.name,loggedOut:false});state.config=config;await vaultWrite(config);await api('/v1/rooms',{method:'POST',token:setupToken,config,body:{room:config.room,role:config.role,token:config.token,join:config.join}});config.state='active';await vaultWrite(config);await activate(config);await invite();
    }else if(form.id==='join-form'){
      const data=parseInvite($('#invite').value,!window.Jazzy),previous=await vaultRead();const config=previous?.state==='joining'&&previous.room===data.room?previous:{state:'joining',server:data.server,room:data.room,role:data.role,token:randomToken(),key:data.key,owner:false};
      if(data.server!==state.auth.server||data.role!==state.auth.role)throw new Error('Log in to the server and account named in this invite.');Object.assign(config,{session:state.auth.session,username:state.auth.username,name:state.auth.name,loggedOut:false});state.config=config;await vaultWrite(config);const result=await api('/v1/rooms/'+config.room+'/join',{method:'POST',config,body:{invite:data.join,token:config.token}});if(result.role!==data.role)throw new Error('This invite is for a different identity.');config.state='active';await vaultWrite(config);await activate(config);toast('You found each other. Welcome to JAZZY. 💙');
    }else if(form.id==='create-form'){
      const caption=$('#caption').value.trim(),kind=state.createKind;const payload={kind,caption};if(kind==='reel'){const raw=$('#reel-url').value.trim();if(raw)payload.url=normalizeReel(raw);if(state.createMedia)payload.media=state.createMedia;if(!payload.url&&!payload.media)throw new Error('Paste an Instagram Reel link or choose a short video.');if(payload.url&&payload.media)throw new Error('Share either a Reel link or your own video in one post.');}else{if(!state.createMedia)throw new Error('Choose a photo or video first.');payload.media=state.createMedia;if(kind==='post')payload.location=$('#location').value.trim();}await publish(payload);state.createMedia=null;state.captionDraft='';state.pendingReel='';navigate(kind==='reel'?'reels':'home');toast(state.demo?'Added to this preview.':'Shared in your little world.');
    }else if(form.id==='chat-form'){
      const text=$('#message').value.trim(),attachment=state.chatMedia;if(!text&&!attachment&&!state.chatFile)return;await publish({kind:'message',text,...(attachment?{media:attachment}:{}),...(state.chatFile?{file:state.chatFile}:{})});$('#message').value='';$('#message').style.height='34px';state.chatMedia=null;state.chatFile=null;$('#chat-attachment').innerHTML='';refreshModel();$('#messages').innerHTML=messageList();window.scrollTo(0,document.body.scrollHeight);
    }else if(form.id==='comment-form'){const text=$('#comment').value.trim();if(!text)return;await publish({kind:'comment',target:form.dataset.id,text});comments(form.dataset.id);}
    else if(form.id==='profile-form'){await publish({kind:'profile',bio:$('#profile-bio').value.trim(),city:$('#profile-city').value.trim(),timezone:$('#profile-zone').value});closeModal();render();toast('Your profile is updated.');}
  }catch(error){if(errorEl){errorEl.hidden=false;errorEl.textContent=error.message;}else toast(error.message||'Something went wrong.');}
  finally{if(button)button.disabled=false;}
});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){sync();if(state.page==='chat')markRead();}});
window.addEventListener('online',()=>sync());
setInterval(()=>sync(),4000);
setInterval(()=>{if(state.page==='home'&&!state.modal&&model.stories.some(e=>Date.parse(e.created)+86400000<=Date.now()))repaint();},60000);
try{const config=await vaultRead();if(config&&!config.loggedOut&&config.session){state.config=config;state.auth={server:config.server,session:config.session,role:config.role,username:config.username,name:config.name};if(config.state==='active')await activate(config);else if(config.state==='joining')await finishFriendJoin(config);else {render();await pollFriends();}}else if(config)login(config.server,config.username||'');else render();}catch(error){$('#app').innerHTML=`<main class="setup-page"><h1>Your keys need attention.</h1><p>${esc(error.message)}</p><p>Keep app data intact and consult the setup guide before resetting this phone.</p></main>`;}
